// Deterministic interoperability corpus generated by the existing browser owners.
import { readFile, writeFile, mkdir } from 'node:fs/promises'
import { createPrivateKey, webcrypto, createHash } from 'node:crypto'
import assert from 'node:assert/strict'
import { encodeGoalRequest, authenticateKey } from '../../src/signed-client.js'
import { importEncryptedKeyProvider, b64url } from '../../src/key-provider.js'
import { readMarks } from '../../src/marks.js'
import { readTerm } from '../../src/prolog-read.js'
import { renderTerm, binary, compound, atom, variable } from '../../src/prolog-term.js'
import { anchoredGoal } from '../../src/world.js'
import { validateGlb } from '../../src/glb-profile.js'

const crypto = webcrypto
const utf8 = s => new TextEncoder().encode(s)
const seed = Buffer.from(Array.from({ length: 32 }, (_, i) => i + 1))
const jwk = createPrivateKey({ key: Buffer.concat([Buffer.from('302e020100300506032b657004220420', 'hex'), seed]), format: 'der', type: 'pkcs8' }).export({ format: 'jwk' })
const network = b64url(new Uint8Array(32).fill(7)), anchor = b64url(new Uint8Array(32).fill(8))
const account = { network, namespace: 'quod:test-λ', anchor, instanceText: 'agent(18446744073709551615).' }
const passphrase = 'public fixture passphrase'
const salt = new Uint8Array(16).fill(4), iv = new Uint8Array(12).fill(5)
const material = await crypto.subtle.importKey('raw', utf8(passphrase), 'PBKDF2', false, ['deriveKey'])
const wrapping = await crypto.subtle.deriveKey({ name: 'PBKDF2', hash: 'SHA-256', salt, iterations: 600000 }, material, { name: 'AES-GCM', length: 256 }, false, ['encrypt'])
const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv, additionalData: utf8('quod-client-key-v1') }, wrapping, utf8(JSON.stringify({ private_jwk: jwk, accounts: [account] })))
const bundle = JSON.stringify({ version: 1, kdf: 'PBKDF2-SHA-256', iterations: 600000, salt: b64url(salt), cipher: 'AES-256-GCM', iv: b64url(iv), ciphertext: b64url(new Uint8Array(ciphertext)), public_key: jwk.x })
const provider = await importEncryptedKeyProvider(bundle, passphrase)
const requestInputs = [
  { goal: 'lobby_reference(Lobby).', deadline: '1900000000000' },
  { goal: "'λ'(<<\"\\x00\\\">>).", deadline: '18446744073709551615' },
].map(({goal, deadline}) => ({ account, operation: b64url(new Uint8Array(32).fill(9)), deadline, goal }))
const requests = await Promise.all(requestInputs.map(async input => {
  const bytes = encodeGoalRequest({ networkIdentity: new Uint8Array(32).fill(7), signingPublicKey: provider.publicKey, operationId: new Uint8Array(32).fill(9), agentNamespace: account.namespace, agentAnchor: new Uint8Array(32).fill(8), agentInstanceText: account.instanceText, mode: 'read', notAfterMs: input.deadline, goal: input.goal })
  return { ...input, bytes: b64url(bytes), signature: b64url(new Uint8Array(await provider.sign(bytes))) }
}))
const challenge = { network_id: network, node_key: anchor, challenge_id: b64url(new Uint8Array(16).fill(2)), server_nonce: b64url(new Uint8Array(32).fill(3)), expires_ms: 1900000000000 }
let challengeNonce, signedChallenge
await authenticateKey({ publicKey: provider.publicKey, sign: async bytes => { signedChallenge = bytes; return provider.sign(bytes) } }, {
  post: async (url, body) => {
    if (url.endsWith('/challenge')) { challengeNonce = body.client_nonce; return challenge }
    return { session_id: 'fixture', expires_ms: 1900000000000 }
  },
})
// Capture the production byte layout; substitute a fixed nonce for reproducibility.
const nonce = new Uint8Array(32).fill(6)
const challengeBytes = new Uint8Array(signedChallenge)
const nonceOffset = utf8('quod.agent.challenge.v1\0').length + 3 * 32 + 16
challengeBytes.set(nonce, nonceOffset)
assert.equal(challengeNonce.length, 43)
const reference = { namespace: 'quod:lobby-test', anchor: new Uint8Array(32).fill(8) }
const lobbyBinding = renderTerm(compound('ontology_ref', [binary(utf8(reference.namespace)), binary(reference.anchor)]))
const lobbyGoal = anchoredGoal(reference, compound(',', [compound('lobby_modes', [variable('Modes')]), compound('lobby_view', [atom('playing'), variable('Scene')])]))
const surface = 'surface(<<"#F9C80E">>,0,900,0,[])'
const depicts = `depicts(<<"quod:test">>,${renderTerm(binary(reference.anchor))},entity(18446744073709551615))`
const mark = (id, kind, size, transform='transform(0,750,0,15,30,45)', material=surface) => `mark(<<"${id}">>,<<"${kind}">>,${size},${transform},${material},label(<<"fixture">>,<<"above">>),${depicts})`
const primitive = mark('box','box','[f(<<"width">>,400),f(<<"height">>,1500),f(<<"depth">>,300)]')
const validMarks = [`[${primitive}]`, `[${mark('group','group','[]','transform(0,0,0,0,0,0)','no_surface')},${mark('sphere','sphere','[f(<<"diameter">>,900)]','relative(<<"group">>,transform(0,0,0,0,0,0))')}]`]
const glbs = []
for (const path of ['client/test/fixtures/asymmetric.glb', 'assets/GLBs/console.glb']) {
  const bytes = await readFile(new URL('../../../' + path, import.meta.url))
  const info = validateGlb(bytes)
  glbs.push({ path, digest: createHash('sha256').update(bytes).digest('hex'), costs: info.costs, boundsMm: info.boundsMm })
}
const g = glbs[0]
validMarks.push(`[${mark('model','mesh',`mesh_asset(asset(<<"${g.digest}">>,<<"model/gltf-binary">>),<<"gltf2-static-v1">>,scale(1000),frame(aabb(${g.boundsMm.join(',')}),pivot(100,0,0),front(<<"+x">>)),resources(${g.costs.map(n=>Math.max(1,n)).join(',')}))`,'transform(0,0,0,0,0,0)','asset_surfaces')}]`)
const normalize = marks => marks.map(m => ({ ...m, depicts: m.depicts && { ontology: m.depicts.ontology, anchor: m.depicts.anchor && b64url(m.depicts.anchor), entityText: renderTerm(m.depicts.entity) } }))
const invalidMarks = [
  `[${primitive},${primitive}]`, `[${primitive.replace(',<<"box">>',',<<"cone">>')}]`,
  `[${primitive.replace('900,0,[]','1001,0,[]')}]`, `[${primitive.replace('400)','400.5)')}]`,
  `[${primitive.replace('<<"above">>','<<"left">>')}]`, '[X]', '[a|b]',
]
for (const text of invalidMarks) assert.throws(()=>readMarks(text), undefined, text)
const validTerms = ['9'.repeat(400), '18446744073709551615', '-18446744073709551616000', "'quod:test'(<<\"\\x00\\\\xff\\\">>,[a,b])", '[f(1),g(-2)]', "'\\x3bb\\'(a)"]
const invalidTerms = ['', 'a b', 'f(a,)', '[a,b', '<<"\\x100\\">>', 'f('.repeat(65)+'a'+')'.repeat(65)]
for (const text of invalidTerms) assert.throws(()=>readTerm(text))
const data = { bundle, passphrase, public_key: b64url(provider.publicKey), account, requests,
  challenge: { value: challenge, nonce: b64url(nonce), bytes: b64url(challengeBytes), signature: b64url(new Uint8Array(await provider.sign(challengeBytes))) },
  lobbyBinding, lobbyGoal, marks: validMarks.map(text=>({text,value:normalize(readMarks(text))})), invalidMarks,
  terms: validTerms.map(text=>({text,canonical:renderTerm(readTerm(text))})), invalidTerms, glbs }
const target = new URL('../../test/fixtures/native-contract/contracts.json', import.meta.url)
if (process.argv.includes('--write')) { await mkdir(new URL('.', target), { recursive: true }); await writeFile(target, JSON.stringify(data,null,2)+'\n') }
else assert.deepEqual(JSON.parse(await readFile(target,'utf8')), data)
console.log('Browser/native conformance corpus verified')
